public class ArgumentImplTest{
private ArgumentImpl arg;
    private WriteableCommandLine commandLine;
    private ListIterator arguments;
    private Option option;

    @Before
    public void before(){
        arg = new ArgumentImpl("arg","desc",1,2,' ',',',null,null,Collections.EMPTY_LIST,1);
        commandLine = mock(WriteableCommandLine.class);
        option = mock(Option.class);
        arguments = mock(ListIterator.class);
    }

    @Test
    public void testProcessValues_noArgs(){
        try{
            arg.processValues(commandLine,arguments,option);
            fail("Expected exception not thrown");
        }catch (Exception e){
        }
    }

    @Test
    public void testProcessValues_oneArg(){
        when(arguments.next()).thenReturn("\"test\"");
        when(arguments.hasNext()).thenReturn(true).thenReturn(false);
        arg.processValues(commandLine,arguments,option);
        verify(commandLine).addValue(option,"test");
    }

    @Test
    public void testProcessValues_multipleArgs(){
        when(arguments.next()).thenReturn("\"test1\"").thenReturn("\"test2\"");
        when(arguments.hasNext()).thenReturn(true).thenReturn(true).thenReturn(false);
        arg.processValues(commandLine,arguments,option);
        verify(commandLine,times(2)).addValue(option,anyString());
    }

    @Test
    public void testProcessValues_optionAsArg(){
        when(arguments.next()).thenReturn("--opt");
        when(arguments.hasNext()).thenReturn(true).thenReturn(false);
        when(commandLine.looksLikeOption(anyString())).thenReturn(true);
        arg.processValues(commandLine,arguments,option);
        verify(commandLine,never()).addValue(option,anyString());
    }

    @Test
    public void testProcessValues_consumeRemaining(){
        arg = new ArgumentImpl("arg","desc",1,2,' ',',',null,"--",Collections.EMPTY_LIST,1);
        when(arguments.next()).thenReturn("--");
        when(arguments.hasNext()).thenReturn(true).thenReturn(false);
        arg.processValues(commandLine,arguments,option);
        verify(commandLine,never()).addValue(option,anyString());
    }

    @Test
    public void testProcessValues_subsequentSplit(){
        arg = new ArgumentImpl("arg","desc",1,2,' ',',',null,null,Collections.EMPTY_LIST,1);
        when(arguments.next()).thenReturn("test1,test2");
        when(arguments.hasNext()).thenReturn(true).thenReturn(false);
        arg.processValues(commandLine,arguments,option);
        verify(commandLine,times(2)).addValue(option,anyString());
    }

    @Test
    public void testProcessValues_subsequentSplit_tooManyArgs(){
        arg = new ArgumentImpl("arg","desc",1,2,' ',',',null,null,Collections.EMPTY_LIST,1);
        when(arguments.next()).thenReturn("test1,test2,test3");
        when(arguments.hasNext()).thenReturn(true).thenReturn(false);
        try{
            arg.processValues(commandLine,arguments,option);
            fail("Expected exception not thrown");
        }catch (OptionException e){
            assertThat(e.getMessage(),containsString(ResourceConstants.ARGUMENT_UNEXPECTED_VALUE));
        }
    }

    @Test
    public void testProcessValues_maxArgsReached(){
        arg = new ArgumentImpl("arg","desc",1,1,' ',',',null,null,Collections.EMPTY_LIST,1);
        when(arguments.next()).thenReturn("\"test1\"").thenReturn("\"test2\"");
        when(arguments.hasNext()).thenReturn(true).thenReturn(true).thenReturn(false);
        arg.processValues(commandLine,arguments,option);
        verify(commandLine).addValue(option,"test1");
    }

    @Test
    public void testProcessValues_stripBoundaryQuotes(){
        when(arguments.next()).thenReturn("\"test\"");
        when(arguments.hasNext()).thenReturn(true).thenReturn(false);
        arg.processValues(commandLine,arguments,option);
        verify(commandLine).addValue(option,"test");
    }

    @Test
    public void testProcessValues_undefaultedValues(){
        when(commandLine.getUndefaultedValues(option)).thenReturn(Collections.singletonList("test"));
        when(arguments.next()).thenReturn("\"test2\"");
        when(arguments.hasNext()).thenReturn(true).thenReturn(false);
        arg.processValues(commandLine,arguments,option);
        verify(commandLine).addValue(option,"test2");
    }
} 
