    public void testGetOptions_withSomeOptions(){
        //given
        Option opt1 = new Option("a","aaa");
        Option opt2 = new Option("b","bbb");
        //when
        cmdLine.addOption(opt1);
        cmdLine.addOption(opt2);
        //then
        assertThat(cmdLine.getOptions().length, is(2));
    }

    @Test
    public void testGetOptions_OptionArrayWithCorrectLength(){
        //given
        Option opt1 = new Option("a","aaa");
        Option opt2 = new Option("b","bbb");
        cmdLine.addOption(opt1);
        cmdLine.addOption(opt2);

        //when
        Option[] options = cmdLine.getOptions();

        //then
        assertThat(options.length, is(2));
    }

    @Test
    public void testGetOptions_equalOptions(){
        //given
        Option opt1 = new Option("a","aaa");
        Option opt2 = new Option("b","bbb");
        cmdLine.addOption(opt1);
        cmdLine.addOption(opt2);

        //when
        Option[] options = cmdLine.getOptions();
        Option[] optionsAgain = cmdLine.getOptions();

        //then
        assertThat(options, arrayContainingInAnyOrder(optionsAgain));
    }

    @Test
    public void testGetOptions_optionsAgainDontAffectOrigin(){
        //given
        Option opt1 = new Option("a","aaa");
        Option opt2 = new Option("b","bbb");
        cmdLine.addOption(opt1);
        cmdLine.addOption(opt2);
        Option[] options = cmdLine.getOptions();

        //when
        options[0] = new Option("test","test");

        //then
        assertThat(cmdLine.getOptions()[0].getLongOpt(), is("aaa"));
    }
}
