        Object result = org.apache.commons.cli.TypeHandler.createValue("test", obj);
        Assert.assertEquals(obj, result);
    }

    @Test
    public void testCreateValueStrClazz() throws Exception {
        Object result = org.apache.commons.cli.TypeHandler.createValue("test", String.class);
        Assert.assertEquals("test", result);
    }

