        Object result = org.apache.commons.cli.TypeHandler.createObject("java.lang.String");
        Assert.assertNotNull(result);
    }

    @Test
    public void testCreateNumber() throws Exception {
        Object result = org.apache.commons.cli.TypeHandler.createNumber("10");
        Assert.assertEquals(10, ((Number)result).intValue());
    }

    @Test
    public void testCreateClass() throws Exception {
        Class<?> result = org.apache.commons.cli.TypeHandler.createClass("java.lang.String");
        Assert.assertEquals(String.class, result);
    }

    @Test
    public void testCreateDate() throws Exception {
        Date result = org.apache.commons.cli.TypeHandler.createDate();
        Assert.assertNotNull(result);
    }

    @Test
    public void testCreateURL() throws Exception {
        URL result = org.apache.commons.cli.TypeHandler.createURL("http://www.google.com");
        Assert.assertNotNull(result);
    }

    @Test
    public void testCreateFile() throws Exception {
        File result = org.apache.commons.cli.TypeHandler.createFile(TEST_FILE);
        Assert.assertNotNull(result);
    }

    @Test
    public void testCreateFiles() throws Exception {
        File[] result = org.apache.commons.cli.TypeHandler.createFiles(TEST_FILE);
        Assert.assertNotNull(result);
        Assert.assertTrue(result.length > 0);
    }
}
